package com.sudoplatform.sudoprivacyinteraction.types.inputs

/**
 * Input object containing the properties required to list analysis results for a virtual presence.
 *
 * @property virtualPresenceId [String] The identifier of the virtual presence to list analysis
 *  results for.
 * @property limit [Int] Number of items to return.
 * @property nextToken [String] A token generated by a previous call, used for pagination.
 */
data class ListAnalysisResultsInput(
    val virtualPresenceId: String,
    val limit: Int? = null,
    val nextToken: String? = null,
)
